def update_ranks(advisers, completed):
    changed = False
    for i in range(len(advisers)):
        qualifies = False
        for year in range(3):
            if completed[i][year] > 6 and completed[i][year+1] > 6:
                qualifies = True
        if qualifies and advisers[i].rank != 1:
            advisers[i].rank = 1
            changed = True
    if not changed:
        return "No rank changed to 1"
    return "Rank updated"

